import pandas as pd

def clean(df):
    df = df.copy()

    if 'Price' in df.columns:
        df['Price'] = (df['Price'].astype(str)
                       .str.replace('$', '', regex=False)
                       .str.replace(',', '', regex=False)
                       .str.strip()
                       .replace({'': None, 'nan': None, 'None': None})
                       .astype(float))

    if 'Region' in df.columns:
        region_map = {
            'north': 'North', 'nort': 'North',
            'south': 'South', 'suoth': 'South',
            'east': 'East',
            'west': 'West', 'wst': 'West'
        }

        def norm_region(x):
            if pd.isna(x):
                return None
            s = str(x).strip()
            return region_map.get(s.lower(), s.title())

        df['Region'] = df['Region'].apply(norm_region)

    if 'Date' in df.columns:
        df['Date'] = pd.to_datetime(df['Date'], errors='coerce')

    if 'Quantity' in df.columns:
        df['Quantity'] = pd.to_numeric(df['Quantity'], errors='coerce')

    if {'Quantity', 'Price', 'Revenue'}.issubset(df.columns):
        df['Revenue'] = df['Quantity'] * df['Price']

    return df


def answer(df):
    d = clean(df)
    d = d[d['Category'].astype(str).str.strip().str.lower() == 'electronics']
    d = d.dropna(subset=['Region'])
    totals = d.groupby('Region', dropna=True)['Revenue'].sum()
    return {str(k): float(v) for k, v in totals.items()}
